static inline void         NSActionCell_SetTarget(NSActionCell self, id target)     { ((void (*)(NSActionCell, SEL, id))bean_msgSend)(self, bean_sel("setTarget:"), target); }
static inline SEL          NSActionCell_Action(NSActionCell self)                   { return ((SEL (*)(NSActionCell, SEL))bean_msgSend)(self, bean_sel("action")); }
static inline void         NSActionCell_SetAction(NSActionCell self, SEL action)    { ((void (*)(NSActionCell, SEL, SEL))bean_msgSend)(self, bean_sel("setAction:"), action); }
static inline NSInteger    NSActionCell_Tag(NSActionCell self)                      { return ((NSInteger (*)(NSActionCell, SEL))bean_msgSend)(self, bean_sel("tag")); }
